        ".....#####.#.######.#.#####.....",
        ".....####.###.####.###.####.....",
        ".....###.#####....#####.###.....",
        ".....##########..##########....."
      ],
      tail: [
        ".....###.######..######.###.....",
        ".....####.####.##.####.####.....",
        ".....#####.####..####.#####.....",
        ".....######.########.######.....",
        ".....#####.#.######.#.#####.....",
        ".....####.###.####.###.####.....",
        ".....###.#####....#####.###.....",
        ".....##########..##########.....",
        "......####################......",
        "......####################......",
        ".......##################.......",
        ".......##################.......",
        "........################........",
        "........################........",
        ".........##############.........",
        ".........##############.........",
        "..........############..........",
        "..........############..........",
        "...........##########...........",
        "...........##########...........",
        "............########............",
        "............########............",
        ".............######.............",
        ".............######.............",
        "..............####..............",
        "..............####..............",
        "...............##...............",
        "...............##...............",
        "................................",
        "................................",
        "................................",
        "................................"
      ],
      turn: [
        "................................",
        "................................",
        "................................",
        "................................",
        "................................",
        "...........#####################",
        ".........#######################",
        "........########################",
        ".......#########################",
        "......##########################",
        "......##########################",
        ".....###########################",
        ".....###########################",
        ".....###########################",
        ".....###########################",
