renderSnakeIconAnimation(canvas) {
  const ctx = canvas.getContext("2d");
  let snake = [{x: 4, y: 3}, {x: 3, y: 3}, {x: 2, y: 3}];
  let food = {x: 8, y: 3};
  let dx = 1;
  let frame = 0;

  const interval = setInterval(() => {
    if (!document.body.contains(canvas)) {
      clearInterval(interval);
      return;
    }
    const style = getComputedStyle(document.body);
    const ink = style.getPropertyValue('--ink').trim() || '#090b0a';
    const line = style.getPropertyValue('--line').trim() || '#1b221d';
    const green = style.getPropertyValue('--green').trim() || '#20ef4f';
    const cyan = style.getPropertyValue('--cyan').trim() || '#91f3a8';

    frame++;
    if (frame % 10 === 0) {
      const head = { x: snake[0].x + dx, y: snake[0].y };
      if (head.x >= 11 || head.x < 1) {
        dx = -dx;
        head.x += dx * 2;
      }
      snake.unshift(head);
      snake.pop();
    }

    ctx.fillStyle = ink;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.strokeStyle = line;
    ctx.lineWidth = 0.5;
    for (let x = 0; x < canvas.width; x += 8) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, canvas.height); ctx.stroke();
    }
    for (let y = 0; y < canvas.height; y += 8) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(canvas.width, y); ctx.stroke();
    }

    const cellSize = 8;
    ctx.fillStyle = cyan;
    ctx.shadowColor = cyan;
    ctx.shadowBlur = 4;
    ctx.fillRect(food.x * cellSize + 1, food.y * cellSize + 1, cellSize - 2, cellSize - 2);
    ctx.shadowBlur = 0;

    snake.forEach((part, idx) => {
      ctx.fillStyle = green;
      ctx.fillRect(part.x * cellSize + 1, part.y * cellSize + 1, cellSize - 2, cellSize - 2);
    });
  }, 80);
}

toolArgs.new_str:
renderSnakeIconAnimation(canvas) {
  const ctx = canvas.getContext("2d");
  const loop = [
    {x: 1, y: 1}, {x: 2, y: 1}, {x: 3, y: 1}, {x: 4, y: 1}, {x: 5, y: 1},
    {x: 5, y: 2}, {x: 5, y: 3}, {x: 5, y: 4}, {x: 5, y: 5},
    {x: 4, y: 5}, {x: 3, y: 5}, {x: 2, y: 5}, {x: 1, y: 5},
    {x: 1, y: 4}, {x: 1, y: 3}, {x: 1, y: 2}
  ];
  let step = 0;

  const interval = setInterval(() => {
    if (!document.body.contains(canvas)) {
      clearInterval(interval);
      return;
    }
    const style = getComputedStyle(document.body);
    const ink = style.getPropertyValue('--ink').trim() || '#090b0a';
    const line = style.getPropertyValue('--line').trim() || '#1b221d';
    const green = style.getPropertyValue('--green').trim() || '#20ef4f';
    const cyan = style.getPropertyValue('--cyan').trim() || '#91f3a8';

    step = (step + 1) % loop.length;

    ctx.fillStyle = ink;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.strokeStyle = line;
    ctx.lineWidth = 0.5;
    for (let x = 0; x <= canvas.width; x += 8) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, canvas.height); ctx.stroke();
    }
    for (let y = 0; y <= canvas.height; y += 8) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(canvas.width, y); ctx.stroke();
    }

    const cellSize = 8;
    const appleX = 3 * cellSize;
    const appleY = 3 * cellSize;
    ctx.fillStyle = '#ff2244';
    ctx.shadowColor = '#ff2244';
    ctx.shadowBlur = 6;
    ctx.fillRect(appleX + 1, appleY + 1, cellSize - 2, cellSize - 2);
    ctx.shadowBlur = 0;

    ctx.fillStyle = green;
    ctx.fillRect(appleX + 3, appleY - 1, 2, 2);

    const snakeLength = 8;
    for (let i = 0; i < snakeLength; i++) {
      const ptIndex = (step - i + loop.length * 100) % loop.length;
      const pt = loop[ptIndex];
      const px = pt.x * cellSize;
      const py = pt.y * cellSize;

      if (i === 0) {
        ctx.fillStyle = cyan;
        ctx.shadowColor = cyan;
        ctx.shadowBlur = 5;
        ctx.fillRect(px + 1, py + 1, cellSize - 2, cellSize - 2);
        ctx.shadowBlur = 0;
      } else {
        ctx.fillStyle = green;
        ctx.shadowColor = green;
        ctx.shadowBlur = 2;
        ctx.fillRect(px + 1.5, py + 1.5, cellSize - 3, cellSize - 3);
        ctx.shadowBlur = 0;
      }
    }
  }, 120);
}

