/* Cyber Snake Arcade App Icon & Modal Styles */
.juegos-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 24px;
  margin-top: 24px;
  pointer-events: none;
}

.snake-app-icon-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  background: var(--panel);
  border: 1px solid var(--line);
  padding: 28px 20px;
  cursor: pointer;
  transition: all 0.2s ease;
  text-align: center;
  pointer-events: auto;
  width: 100%;
}

.snake-app-icon-card:hover {
  border-color: var(--green);
  transform: translateY(-3px);
  box-shadow: 0 0 20px color-mix(in srgb, var(--green) 20%, transparent);
}

.snake-app-icon {
  width: 72px;
  height: 72px;
  background: var(--ink);
  border: 1px solid var(--green);
  display: grid;
  place-items: center;
  box-shadow: inset 0 0 10px color-mix(in srgb, var(--green) 15%, transparent);
  position: relative;
  pointer-events: none;
}

.snake-icon-canvas {
  width: 56px;
  height: 56px;
  display: block;
  pointer-events: none;
}

.snake-icon-label {
  font-family: var(--display);
