        "...............##...............",
        "...............##...............",
        "................................",
        "................................",
        "................................",
        "................................"
      ],
      turn: [
        "................................",
        "................................",
        "................................",
        "................................",
        "................................",
        "...........#####################",
        ".........#######################",
        "........########################",
        ".......#########################",
        "......##########################",
        "......##########################",
